function jstr(s: string): string {
  return JSON.stringify(s);
}

// encodeOpaque carries an opaque (`any` / RawMessage) value VERBATIM: the
// key order from JSON.parse is preserved, matching the Go and Rust codecs'
// byte-carry of opaque values. Opaque values are never sorted.
function encodeOpaque(v: unknown): string {
  return JSON.stringify(v);
}

