  labels: Record<string, string>;
  // The name of the underlying Component.
  component: string;
  // The exact Semantic Version of the Component resolved during compilation.
  resolved_version: string;
  // The deployment wave inherited from the containing boundary's `syncWave` field (default 0; negative permitted). On K8s and Helm the wave is what orders the deployment: it becomes an `argocd.argoproj.io/sync-wave` annotation, and on a resource the chart already marks as a Helm hook it also becomes that hook's `helm.sh/hook-weight`. On compose the value both is recorded as a service label and orders the services of the file it renders into, through `depends_on` between them. On cloudformation it orders provisioning of the stack a dispatch group assembles into, every resource in a wave being declared to depend on the resources of the wave before it: the order they are created in and, in reverse, the order they are deleted in, never readiness, because a stack template expresses no notion of a resource being ready. On terraform it produces no ordering artifact and travels with the node's build provenance.
  sync_wave?: number;
  // The physical spatial hierarchy mapped from the Release boundaries (e.g., 'aws-prod/eks-main/payments'). Allows rendering plugins to generate boundary-aware unique identifiers.
  boundary_path?: string;
  // The logical spatial hierarchy mapped from the Aggregate subsystems (e.g., 'finance-module/ledger-api'). Allows rendering plugins to generate logical metadata tags.
  subsystem_path?: string;
  // True when this node's subsystem was synthesized by the compiler — the `default` subsystem created for an Aggregate that declares top-level `components` rather than named `subsystems`. Derived provenance, never authored: it distinguishes the synthesized `default` from a subsystem a user explicitly named `default`. Independent of `synthesized_boundary` (a node may be synthesized on either axis or both). Absent (false) for every authored subsystem.
  synthesized_subsystem?: boolean;
  // True when this node's boundary was synthesized by the compiler — the `default` boundary created for a Release that declares top-level `components` rather than named `boundaries`. Derived provenance, never authored: it distinguishes the synthesized `default` from a boundary a user explicitly named `default`, and routes the node's artifacts to `dist/` flat instead of `dist/boundaries/default/`. Absent (false) for every authored boundary.
  synthesized_boundary?: boolean;
  catalog_metadata?: CatalogMetadata;
  // Immutable, intrinsic component characteristics authored by the Platform Architect in Domain 2.
  catalog_annotations?: Record<string, string>;
  // Physical topology strings and Ops realities cascading from boundaries in the Release.
  release_annotations?: Record<string, string>;
  // Cognitive metadata, developer intent, and FinOps cascading from subsystems in the Aggregate.
  aggregate_annotations?: Record<string, string>;
  // Component-level self-inject block carried from the Aggregate; the agnostic injection routing the node declares for itself. Opaque at this schema layer; a policy plugin that reads it parses the bytes.
  self_inject?: unknown;
  // Workspace-relative path of the Aggregate file where this node was authored. Root-tier nodes carry the root Aggregate's path; sub-aggregate nodes carry the imported Aggregate's file path. The emitter normalizes against the workspace root (the directory containing .aggrega-config.yaml) so the IR wire shape stays byte-identical across developer machines whose workspaces live at different absolute paths. Consumers that filter diagnostics per file resolve the field against the same workspace root before comparison. Empty when the emitter has no workspace concept (e.g., synthetic test fixtures); the field is omitted from the JSON when empty.
